  function levenshteinDistance(a, b) {
    const m = a.length;
    const n = b.length;
    const dp = Array.from({ length: m + 1 }, () => Array(n + 1).fill(0));
    for (let i2 = 0; i2 <= m; i2++) dp[i2][0] = i2;
    for (let j2 = 0; j2 <= n; j2++) dp[0][j2] = j2;
    for (let i2 = 1; i2 <= m; i2++) {
      for (let j2 = 1; j2 <= n; j2++) {
        if (a[i2 - 1] === b[j2 - 1]) {
          dp[i2][j2] = dp[i2 - 1][j2 - 1];
        } else {
          dp[i2][j2] = 1 + Math.min(
            dp[i2 - 1][j2],
            // حذف
            dp[i2][j2 - 1],
            // إضافة
            dp[i2 - 1][j2 - 1]
            // استبدال
          );
        }
      }
    }
    let i = m;
    let j = n;
    const operations = [];
    while (i > 0 || j > 0) {
      if (i > 0 && j > 0 && a[i - 1] === b[j - 1]) {
        i--;
        j--;
      } else if (i > 0 && j > 0 && dp[i][j] === dp[i - 1][j - 1] + 1) {
        operations.unshift({ op: "replace", indexA: i - 1, indexB: j - 1 });
        i--;
        j--;
      } else if (i > 0 && dp[i][j] === dp[i - 1][j] + 1) {
        operations.unshift({ op: "delete", indexA: i - 1, indexB: j });
        i--;
      } else if (j > 0 && dp[i][j] === dp[i][j - 1] + 1) {
        operations.unshift({ op: "insert", indexA: i, indexB: j - 1 });
        j--;
      } else {
        break;
      }
    }
    return { distance: dp[m][n], operations };
  }
